-- ============================================================================
-- Revalidacao "30 jogadores" v2 (snapshot 31/08/2026) do Adivinhe o Jogador.
-- Substitui a edicao "consolidada" anterior (26/08/2026): passagens que
-- antes eram uma linha so com periodo composto (ex.: '2008-2009; 2011-2012')
-- agora sao linhas cronologicas separadas. Quando a fonte so fecha o total
-- somado de duas+ passagens pelo mesmo clube, essas linhas ficam com
-- appearances/goals nulos e o total mora em aggregate_stats (nunca dividido
-- entre as passagens). Rode este arquivo no SQL Editor do Supabase.
--
-- on conflict do update -- seguro rodar de novo, so atualiza os 30
-- jogadores existentes (nao apaga nenhum outro registro).
-- ============================================================================

alter table public.career_players
  add column if not exists aggregate_stats jsonb not null default '[]'::jsonb;

on conflict (id) do update set
  answer = excluded.answer,
  accepted_answers = excluded.accepted_answers,
  position = excluded.position,
  club_career = excluded.club_career,
  national_teams = excluded.national_teams,
  aggregate_stats = excluded.aggregate_stats,
  sort_order = excluded.sort_order;
